WITH unpacked AS (SELECT id, log_ts, level, latency_ms, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, CAST((status_code & 8) != 0 AS INT) AS flag_bit8, SIZE(context) AS num_context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec FROM app_logs) SELECT *, DENSE_RANK() OVER w_recent num_context_dense_rank, SUM(flag_bit8) OVER (PARTITION BY level ORDER BY num_context, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_flag_bit8, AVG(flag_bit8) OVER w_part flag_bit8_avg_5, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY level), 4) latency_ms_share, PERCENT_RANK() OVER (PARTITION BY level ORDER BY flag_bit8 DESC NULLS LAST) flag_bit8_percent_rank FROM unpacked WINDOW w_recent AS (PARTITION BY level ORDER BY num_context), w_part AS (PARTITION BY level ORDER BY duration_sec, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW)
